param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'decimal-bit-copy-array-bridges-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json
function Failure($Record){$e=$Record.Exception;while($e -is [Reflection.TargetInvocationException] -or $e -is [Management.Automation.MethodInvocationException]){$e=$e.InnerException};return [ordered]@{ok=$false;exception=$e.GetType().FullName;messageUnits=[int[]][char[]]$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})}}
$op=[Reflection.Emit.OpCodes];$span=[type]'System.Span[int]';$spanConstructor=$span.GetConstructor([type[]]@([int[]]))
$get=[Reflection.Emit.DynamicMethod]::new('GetBitsArray',[int],[type[]]@([decimal],[int[]]));$il=$get.GetILGenerator();$il.Emit($op::Ldarg_0);$il.Emit($op::Ldarg_1);$il.Emit($op::Newobj,$spanConstructor);$il.Emit($op::Call,[decimal].GetMethod('GetBits',[type[]]@([decimal],$span)));$il.Emit($op::Ret);$getBits=$get.CreateDelegate([Func[decimal,int[],int]])
$try=[Reflection.Emit.DynamicMethod]::new('TryGetBitsArray',[bool],[type[]]@([decimal],[int[]],[int[]]));$il=$try.GetILGenerator();$il.Emit($op::Ldarg_0);$il.Emit($op::Ldarg_1);$il.Emit($op::Newobj,$spanConstructor);$il.Emit($op::Ldarg_2);$il.Emit($op::Ldc_I4_0);$il.Emit($op::Ldelema,[int]);$il.Emit($op::Call,[decimal].GetMethod('TryGetBits',[type[]]@([decimal],$span,[int].MakeByRefType())));$il.Emit($op::Ret);$tryBits=$try.CreateDelegate([Func[decimal,int[],int[],bool]])
$rows=[Collections.Generic.List[object]]::new()
for($index=0;$index -lt $plan.bits.Count;$index++){$value=[decimal]::new([int[]]$plan.bits[$index]);foreach($length in $plan.lengths){foreach($route in @('get','try','try-alias')){if($route -eq 'try-alias' -and $length -le 0){continue};$destination=$null;if($length -ge 0){$destination=[int[]]::new($length);for($slot=0;$slot -lt $length;$slot++){$destination[$slot]=1000+$slot}};$written=[int[]]@(99);if($route -eq 'try-alias'){$written=$destination};try{if($route -eq 'get'){$actual=$getBits.Invoke($value,$destination)}else{$actual=$tryBits.Invoke($value,$destination,$written)};$result=[ordered]@{ok=$true;value=$actual}}catch{$result=Failure $_};$rows.Add([ordered]@{index=$index;length=$length;route=$route;result=$result;written=$written[0];buffer=$destination;afterBits=[decimal]::GetBits($value)})}}}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();culture='Invariant';rows=$rows.ToArray();qualification=$plan.qualification};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 18 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS Decimal bit-copy array bridges: $($rows.Count) native calls"
